  let map = null, cur = 'en';
  L.set = function (code) {
    cur = L.T[code] ? code : 'en';
    map = null;
    if (cur !== 'en') {
      map = new Map();
      // interface text first, then menu labels (menus win where both lists have the same English)
      const ui = L.UI_T && L.UI_T[cur];
      if (ui) L.UI_EN.forEach((e, i) => { if (ui[i]) map.set(e, ui[i]); });
      L.EN.forEach((e, i) => map.set(e, L.T[cur][i]));
    }
    document.documentElement.lang = cur;
    if (L.DOM) L.DOM.apply();
  };
  L.code = () => cur;
  // translate one menu label (exact match, or "Prefix: rest" / "Repeat Name" built from known parts)
  L.t = function (s) {
    if (!map || !s) return s;
    if (map.has(s)) return map.get(s);
    const k = s.indexOf(': ');
    if (k > 0) { const a = s.slice(0, k), b = s.slice(k + 2), ta = map.get(a) || map.get(a + ':'), tb = map.get(b), tbb = b.replace(/ \((.*)\)$/, (m, x) => ' (' + (map.get(x) || x) + ')'); if (ta || tb) return (ta ? ta.replace(/[:：]$/, '') : a) + (/^(zh|ja)$/.test(cur) ? '：' : ': ') + (tb || tbb); }
    if (s.startsWith('Repeat ')) { const r = s.slice(7); return (map.get('Repeat') || 'Repeat') + ' ' + (map.get(r) || r); }
    if (s.endsWith('…') && map.has(s.slice(0, -1))) return map.get(s.slice(0, -1)) + '…';
    return s;
  };
  ND.Lang = L;
